steps.code:
# Verify no other pending roommate requests remain for this calendar month (June 2023)
# Fetch all pending requests (paginate) and filter by roommate and June
pending_all = []
page_index = 0
while True:
    page = apis.venmo.show_received_payment_requests(access_token=access_token, status='pending', page_index=page_index, page_limit=20)
    if not page or len(page) == 0:
        break
    pending_all.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Filter for roommates and June
roommate_ids = {r['contact_id'] for r in roommates}
june_pending_roommate = []
for req in pending_all:
    # Check if sender is a roommate (by name or email? We have contact_id but request may have sender info)
    # The request structure likely has sender_name or sender_id. We'll check by name.
    sender = req.get('sender_name', '')
    # Also check if created in June 2023
    created = req.get('created', '')
    if '2023-06' in created:
        # Check if sender matches any roommate name
        for r in roommates:
            full_name = f"{r['first_name']} {r['last_name']}"
            if full_name.lower() in sender.lower():
                june_pending_roommate.append(req)
                break

print("Remaining pending roommate June requests:", june_pending_roommate)
if june_pending_roommate:
    print("Still pending, need to approve")
else:
    print("All roommate June requests are approved or denied; no pending remain.")

